// Guest memory and PS2 arithmetic for the readable port (src/port/).
//
// Ported functions run on the host but keep all game state where the original code keeps it:
// in the PS2's main memory (RDRAM) and scratchpad. Structs from config/types/ are laid over that
// memory (game_types.h, generated by tools/port_types.py); their pointer fields are 32-bit guest
// addresses, wrapped in GuestPtr<T>.
//
// Floating point must give the same bits as the recompiled code, which follows the PS2 FPU (no
// denormals, no Inf/NaN, saturating overflow). Use ps2f instead of float for any value that takes
// part in arithmetic.

#pragma once

#include "ps2_runtime.h"
#include "ps2_runtime_macros.h"

#include <cstddef>
#include <cstdint>
#include <cstring>
#include <type_traits>

namespace port
{
    // Set by port::install() before any ported function runs.
    inline uint8_t *g_rdram = nullptr;
    inline uint8_t *g_scratchpad = nullptr;

    [[noreturn]] void fatal(const char *what, uint32_t address);

    // Host address of a guest address in RDRAM (any KSEG mirror) or the scratchpad. Ported code never
    // touches hardware registers through this; those go through the runtime like the original does.
    inline uint8_t *host(uint32_t address)
    {
        if (address >= PS2_SCRATCHPAD_BASE && address < PS2_SCRATCHPAD_BASE + PS2_SCRATCHPAD_SIZE)
            return g_scratchpad + (address - PS2_SCRATCHPAD_BASE);
        if (PS2Runtime::isSpecialAddress(address))
            fatal("guest pointer to a hardware address", address);
        return g_rdram + (address & PS2_RAM_MASK);
    }

    // Guest address of a host pointer into RDRAM or the scratchpad.
    inline uint32_t guest(const void *pointer)
    {
        const uint8_t *p = static_cast<const uint8_t *>(pointer);
        if (p >= g_scratchpad && p < g_scratchpad + PS2_SCRATCHPAD_SIZE)
            return PS2_SCRATCHPAD_BASE + static_cast<uint32_t>(p - g_scratchpad);
        if (p >= g_rdram && p < g_rdram + PS2_RAM_SIZE)
            return static_cast<uint32_t>(p - g_rdram);
        fatal("host pointer outside guest memory", 0u);
    }

    template <typename T>
    T load(uint32_t address)
    {
        T value;
        std::memcpy(&value, host(address), sizeof(T));
        return value;
    }

    template <typename T>
    void store(uint32_t address, T value)
    {
        std::memcpy(host(address), &value, sizeof(T));
    }
}

namespace mm
{
    // A 32-bit pointer as the game stores it. Same size and layout as the guest's pointer, so structs
    // that contain it keep the guest layout.
    template <typename T>
    struct GuestPtr
    {
        uint32_t address;

        T *get() const { return address ? reinterpret_cast<T *>(port::host(address)) : nullptr; }
        T *operator->() const { return get(); }
        T &operator*() const { return *get(); }
        T &operator[](std::ptrdiff_t i) const { return get()[i]; }
        explicit operator bool() const { return address != 0; }
        bool operator==(const GuestPtr &other) const { return address == other.address; }
        bool operator!=(const GuestPtr &other) const { return address != other.address; }

        static GuestPtr of(const T *pointer) { return GuestPtr{pointer ? port::guest(pointer) : 0u}; }
    };

    template <>
    struct GuestPtr<void>
    {
        uint32_t address;

        void *get() const { return address ? port::host(address) : nullptr; }
        explicit operator bool() const { return address != 0; }
        bool operator==(const GuestPtr &other) const { return address == other.address; }
        bool operator!=(const GuestPtr &other) const { return address != other.address; }
    };

    static_assert(sizeof(GuestPtr<int>) == 4 && std::is_standard_layout_v<GuestPtr<int>> &&
                  std::is_trivially_copyable_v<GuestPtr<int>>);

    // A global variable of the game at a fixed guest address (game_globals.h).
    template <typename T>
    struct GuestVar
    {
        uint32_t address;

        T get() const { return port::load<T>(address); }
        void set(T value) const { port::store<T>(address, value); }
    };

    // A float with PS2 FPU arithmetic, through the same helpers the recompiled code uses
    // (FPU_ADD_S -> ps2_fadd ...). The conversion back to float is explicit so that host float
    // arithmetic cannot slip in by accident. Comparisons are the host's, as in the recompiled code.
    struct ps2f
    {
        float v;

        ps2f() = default;
        constexpr ps2f(float value) : v(value) {}
        explicit constexpr operator float() const { return v; }

        ps2f &operator+=(ps2f o) { v = ps2_fadd(v, o.v); return *this; }
        ps2f &operator-=(ps2f o) { v = ps2_fsub(v, o.v); return *this; }
        ps2f &operator*=(ps2f o) { v = ps2_fmul(v, o.v); return *this; }
        ps2f &operator/=(ps2f o) { v = ps2_fdiv(v, o.v); return *this; }
    };

    inline ps2f operator+(ps2f a, ps2f b) { return ps2_fadd(a.v, b.v); }
    inline ps2f operator-(ps2f a, ps2f b) { return ps2_fsub(a.v, b.v); }
    inline ps2f operator*(ps2f a, ps2f b) { return ps2_fmul(a.v, b.v); }
    inline ps2f operator/(ps2f a, ps2f b) { return ps2_fdiv(a.v, b.v); }
    inline ps2f operator-(ps2f a) { return -a.v; }
    inline bool operator<(ps2f a, ps2f b) { return a.v < b.v; }
    inline bool operator<=(ps2f a, ps2f b) { return a.v <= b.v; }
    inline bool operator>(ps2f a, ps2f b) { return a.v > b.v; }
    inline bool operator>=(ps2f a, ps2f b) { return a.v >= b.v; }
    inline bool operator==(ps2f a, ps2f b) { return a.v == b.v; }
    inline bool operator!=(ps2f a, ps2f b) { return a.v != b.v; }

    inline ps2f sqrt(ps2f a) { return ps2_fsqrt(a.v); }
    inline ps2f abs(ps2f a) { return FPU_ABS_S(a.v); }
    // cvt.w.s and trunc.w.s as the recompiled code does them.
    inline int32_t toIntRound(ps2f a) { return FPU_CVT_W_S(a.v); }
    inline int32_t toIntTrunc(ps2f a) { return FPU_TRUNC_W_S(a.v); }
    inline ps2f fromInt(int32_t i) { return FPU_CVT_S_W(i); }

    static_assert(sizeof(ps2f) == 4 && std::is_trivially_copyable_v<ps2f>);
}
